package org.apache.commons.lang.math;

import java.io.*;
import java.math.*;
import java.math.BigInteger;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class Fraction_reduce_TriageGen1Test {

    @Test
    public void testReduce_AlreadyReduced() {
        // gcd(3, 5) is 1. Should return 'this' (same object or equal)
        Fraction fraction = Fraction.getFraction(3, 5);
        Fraction reduced = fraction.reduce();

        assertSame("Should return the same instance when gcd is 1", fraction, reduced);
        assertEquals(3, reduced.getNumerator());
        assertEquals(5, reduced.getDenominator());
    }

    @Test
    public void testReduce_NeedsReduction() {
        // gcd(6, 8) is 2. Should return a new Fraction(3, 4)
        Fraction fraction = Fraction.getFraction(6, 8);
        Fraction reduced = fraction.reduce();

        assertNotSame("Should return a new instance when reduction occurs", fraction, reduced);
        assertEquals(3, reduced.getNumerator());
        assertEquals(4, reduced.getDenominator());
    }

    @Test
    public void testReduce_NegativeNumerator() {
        // gcd(abs(-10), 20) -> gcd(10, 20) is 10. Should return (-1, 2)
        Fraction fraction = Fraction.getFraction(-10, 20);
        Fraction reduced = fraction.reduce();

        assertEquals(-1, reduced.getNumerator());
        assertEquals(2, reduced.getDenominator());
    }

    @Test
    public void testReduce_LargeGCD() {
        // gcd(100, 100) is 100. Should return (1, 1)
        Fraction fraction = Fraction.getFraction(100, 100);
        Fraction reduced = fraction.reduce();

        assertEquals(1, reduced.getNumerator());
        assertEquals(1, reduced.getDenominator());
    }

    @Test
    public void testReduce_NumeratorIsZero() {
        // gcd(0, 5) is 5. Should return (0, 1)
        Fraction fraction = Fraction.getFraction(0, 5);
        Fraction reduced = fraction.reduce();

        assertEquals(0, reduced.getNumerator());
        assertEquals(1, reduced.getDenominator());
    }
}
